import { useEffect, useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';

function Dashboard() {
  const navigate = useNavigate();
  const [userData, setUserData] = useState({ name: 'Пользователь' });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchUserData = async () => {
      try {
        setLoading(true);
        const token = localStorage.getItem('authToken');

        if (!token) {
          throw new Error('Токен не найден');
        }

        const response = await fetch('http://127.0.0.1:8000/api/user', {
          method: 'GET',
          headers: {
            'Authorization': `Bearer ${token}`,
            'Content-Type': 'application/json',
            'Accept': 'application/json'
          },
          credentials: 'include' // Важно для Sanctum
        });

        const text = await response.text(); // Сначала читаем как текст
        console.log('Raw response:', text);

        try {
          const data = text ? JSON.parse(text) : {};

          if (!response.ok) {
            throw new Error(data.message || `HTTP error! status: ${response.status}`);
          }

          if (data.user && data.user.name) {
            setUserData(data.user);
          } else {
            throw new Error('Неверный формат данных пользователя');
          }
        } catch (jsonError) {
          throw new Error(`Ошибка парсинга JSON: ${jsonError.message}`);
        }
      } catch (error) {
        console.error('Ошибка:', error);
        setError(error.message);
      } finally {
        setLoading(false);
      }
    };

    fetchUserData();
  }, []);

  const handleLogout = async () => {
    try {
      const response = await fetch('http://127.0.0.1:8000/api/logout', {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('authToken')}`,
          'Content-Type': 'application/json'
        },
        credentials: 'include'
      });

      if (!response.ok) {
        throw new Error('Ошибка при выходе');
      }

      localStorage.removeItem('authToken');
      navigate('/login');
    } catch (error) {
      console.error('Ошибка выхода:', error);
      setError(error.message);
    }
  };

  // ... остальной код компонента
}

export default Dashboard;
